<?php use App\Core\Countries; $er = fn($k) => $errors[$k] ?? ''; $v = fn($k) => $u[$k] ?? ''; ?>
<div class="be_page"><div class="be_pagehead"><h1><?= e($isEdit ? t('users.edit') : t('users.add')) ?></h1></div><div class="be_card"><?= errors_summary($errors) ?>
<form class="cmp_form be_form" method="post" action="<?= e(url('users', 'form', !empty($u['id']) ? [$u['id']] : [])) ?>"><?= csrf_field() ?><div class="fields">
<?= field(t('reg.given'), 'given_name', $v('given_name'), ['required' => true, 'maxlength' => 120, 'error' => $er('given_name')]) ?><?= field(t('reg.family'), 'family_name', $v('family_name'), ['maxlength' => 120]) ?>
<?= field(t('reg.affiliation'), 'affiliation', $v('affiliation'), ['maxlength' => 255]) ?><?= field(t('reg.country'), 'country', $v('country'), ['type' => 'select', 'options' => Countries::all(), 'required' => true, 'error' => $er('country')]) ?>
<?= field(t('reg.email'), 'email', $v('email'), ['type' => 'email', 'required' => true, 'maxlength' => 190, 'error' => $er('email')]) ?>
<?php if (!$isEdit): ?><?= field(t('reg.username'), 'username', $v('username'), ['required' => true, 'maxlength' => 32, 'error' => $er('username'), 'help' => t('reg.username_help')]) ?><?php else: ?><p class="muted"><?= e(t('login.username')) ?>: <strong><?= e($u['username']) ?></strong></p><?php endif; ?>
<?= field($isEdit ? t('users.new_password') : t('reg.password'), 'password', '', ['type' => 'password', 'required' => !$isEdit, 'maxlength' => 72, 'error' => $er('password'), 'help' => $isEdit ? t('users.password_keep') : '']) ?>
<?php if (!$isEdit): ?><fieldset class="be_fs"><legend><?= e(t('users.roles')) ?></legend><?php foreach ($groups as $g): ?><div class="optin"><label><input type="checkbox" name="groups[]" value="<?= (int)$g['id'] ?>"<?= in_array((int)$g['id'], $chosen, true) ? ' checked' : '' ?>> <?= e($g['name']) ?></label></div><?php endforeach; ?></fieldset>
<?= checkbox('must_change', e(t('users.must_change')), true) ?><?= checkbox('send_welcome', e(t('users.send_welcome')), true) ?><?php endif; ?></div>
<div class="buttons"><button class="submit" type="submit"><?= e(t('wizard.save')) ?></button><a href="<?= e(url('users')) ?>"><?= e(t('wizard.cancel')) ?></a></div></form></div></div>
